// THIS CODE MAKES THE CONTEXT FOR THE AI AGENT

// Get the client data - handle different response formats
let client;
if (Array.isArray($json)) {
  // If Supabase returns an array
  client = $json[0];
} else if ($json && $json.id) {
  // If Supabase returns an object directly
  client = $json;
} else {
  // Fallback - return error
  return { error: 'No client data found' };
}

// Safety check
if (!client || !client.id) {
  return { error: 'Client data missing required fields' };
}

// Build list of valid roles
const rolesList = [];
const rates = client.contract_terms?.rates_by_role || {};

for (const [roleName, roleData] of Object.entries(rates)) {
  if (roleData && roleData.charge_rate > 0 && roleData.pay_rate > 0) {
    rolesList.push(roleName);
  }
}

// Build list of locations
const locationsList = client.internal_locations || [];

// Get shift times
const dayStart = client.day_shift_start || '08:00';
const dayEnd = client.day_shift_end || '20:00';
const nightStart = client.night_shift_start || '20:00';
const nightEnd = client.night_shift_end || '08:00';

// Create the context message for the AI
const contextString = `
CLIENT INFORMATION:
- Client Name: ${client.name}
- Client ID: ${client.id}
- Agency ID: ${client.agency_id}

AVAILABLE ROLES:
${rolesList.join(', ')}

AVAILABLE LOCATIONS:
${locationsList.join(', ')}

SHIFT TIMES:
- Day Shift: ${dayStart} to ${dayEnd}
- Night Shift: ${nightStart} to ${nightEnd}

RATE INFORMATION:
${rolesList.map(role => {
  const rate = rates[role];
  return `- ${role}: Pay £${rate.pay_rate}/hour, Charge £${rate.charge_rate}/hour`;
}).join('\n')}
`;

return {
  contextString,
  client_data: client,
  rolesList,
  locationsList,
  rates
};

// THIS CODE EXTRACTS THE BOOKING DATA FROM THE AI RESPONSE
const output = $json.output || '';

// Find the JSON in the response
const jsonMatch = output.match(/\{[^{}]*\}/);
if (!jsonMatch) {
  return { error: 'No booking data found' };
}

let bookingData = {};
try {
  bookingData = JSON.parse(jsonMatch[0]);
} catch (e) {
  return { error: 'Invalid JSON' };
}

// Get context data
const contextData = $('Build AI Context').first().json;
const clientData = contextData.client_data;
const rates = contextData.rates;

// Prepare array for all shifts
const allShifts = [];

// Handle both single booking (legacy) and bulk bookings array
const bookings = bookingData.bookings || [bookingData];

for (const booking of bookings) {
  // Skip invalid entries
  if (!booking.role || !booking.date) continue;

  // STRICT VALIDATION: Check rates
  const roleRate = rates[booking.role];
  if (!roleRate || roleRate.pay_rate <= 0) {
    throw new Error(`CRITICAL ERROR: Role '${booking.role}' has invalid rates (£0). Cannot proceed.`);
  }

  // Calculate shift times
  let startTime, endTime;
  if (booking.shift === 'night') {
    startTime = clientData.night_shift_start;
    endTime = clientData.night_shift_end;
  } else {
    startTime = clientData.day_shift_start;
    endTime = clientData.day_shift_end;
  }

  // Calculate duration in hours
  const [startHour, startMin] = startTime.split(':').map(Number);
  const [endHour, endMin] = endTime.split(':').map(Number);
  let duration = endHour - startHour + (endMin - startMin) / 60;
  if (duration < 0) duration = duration + 24; // Handle night shift

  // EXPAND QUANTITY: Create multiple shifts if quantity > 1
  const quantity = booking.quantity || 1;

  for (let i = 0; i < quantity; i++) {
    allShifts.push({
      client_id: clientData.id,
      agency_id: clientData.agency_id,
      date: booking.date,
      start_time: startTime,
      end_time: endTime,
      role_required: booking.role,
      shift_type: booking.shift,
      status: 'open',
      urgency: booking.urgency,
      notes: booking.notes || '',
      location: booking.location || '',
      work_location_within_site: booking.location || '',
      pay_rate: roleRate.pay_rate,
      charge_rate: roleRate.charge_rate,
      duration_hours: Math.round(duration * 100) / 100,
      created_by: 'AI Agent',
      shift_journey_log: [{
        state: 'created',
        timestamp: new Date().toISOString(),
        method: 'ai_agent',
        user_id: 'AI_AGENT'
      }],
      created_date: new Date().toISOString()
    });
  }
}

// Return single object for RPC call (Atomic Batch)
return [{ shifts_data: allShifts }];

